function evidence = f90_xbatt09_extract_candidate_evidence( ...
        modelPath, outputDir)
%F90_XBATT09_EXTRACT_CANDIDATE_EVIDENCE Replay the public contact monitor.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end
[taskRoot, sharedRoot] = localRoots("F90-XBATT-09");
addpath(sharedRoot, "-begin");
cleanup = onCleanup(@() rmpath(sharedRoot)); %#ok<NASGU>
official = jsondecode(fileread(simuverity_official_scenarios_path()));
spec = struct( ...
    "schema", "simuverity.f90-xbatt09-evidence.v1", ...
    "task_id", "F90-XBATT-09", ...
    "profile_path", fullfile(taskRoot, "reference", "DischargeCycle.mat"), ...
    "scenarios", official.scenarios, ...
    "output_contract", localOutputs, ...
    "input_builder", @localInputs, ...
    "requested_input_builder", @localRequested, ...
    "stop_time", @(~,~) 100.0, ...
    "postprocess", @localPostprocess, ...
    "static_audit", @localAudit, ...
    "evidence_sample_s", 0.5);
evidence = simuverity_run_candidate_evidence( ...
    modelPath, outputDir, spec);
end

function rows = localOutputs
rows = localRows(["assembly_voltage", "contact_state", ...
    "battery_state"], [15 30 3]);
rows(2).interpolation = "previous";
end

function inputs = localInputs(scenario, spec)
payload = load(spec.profile_path, char(scenario.profile));
profile = double(payload.(char(scenario.profile)));
assert(size(profile, 2) == 2 && numel(profile(:,1)) >= 2 && ...
    all(isfinite(profile), "all") && all(diff(profile(:,1)) > 0) && ...
    abs(profile(1,1)) <= 1e-9 && abs(profile(end,1) - 100) <= 1e-6, ...
    "SimuVerity:F90:XBATT09:OfficialProfile", ...
    "Fixed official current profile violates the public input contract.");
inputs = struct("xbatt09_input", struct( ...
    "current_time_s", profile(:,1), ...
    "current_A", double(scenario.current_scale) .* profile(:,2), ...
    "contact_fault_enable", logical(scenario.contact_fault_enable), ...
    "contact_fault_time_s", double(scenario.contact_fault_time_s)));
end

function requested = localRequested(scenario, ~)
requested = rmfield(scenario, "id");
end

function row = localPostprocess(row, outputs, scenario, ~)
t = double(outputs.time_s(:));
assemblyChannels = cellstr(compose( ...
    "parallel_assembly_voltage_%02d_V", 1:15));
contactChannels = [cellstr(compose("contact_symptom_%02d", 1:15)), ...
    cellstr(compose("contact_error_%02d", 1:15))];
batteryChannels = {"pack_voltage_V", "pack_current_A", ...
    "parallel_assembly_voltage_spread_V"};
row.logs = struct( ...
    "assembly_voltage", localLog(t, outputs.assembly_voltage, ...
        assemblyChannels, repmat({"V"}, 1, 15)), ...
    "contact_state", localLog(t, outputs.contact_state, ...
        contactChannels, repmat({"1"}, 1, 30)), ...
    "battery_state", localLog(t, outputs.battery_state, ...
        batteryChannels, {"V", "A", "V"}));
row.input = struct( ...
    "profile", char(scenario.profile), ...
    "current_scale", double(scenario.current_scale), ...
    "contact_fault_enable", logical(scenario.contact_fault_enable), ...
    "contact_fault_time_s", double(scenario.contact_fault_time_s));
row.outputs = outputs;
row.simulate_pass = row.simulation_pass;
row.valid = row.output_contract.all_required_pass && ...
    numel(t) == 201 && t(1) <= 1e-9 && abs(t(end) - 100) <= 1e-6;
end

function log = localLog(time, data, channels, units)
log = struct("time", time, "data", double(data), ...
    "channels", {channels}, "units", {units});
end

function audit = localAudit(model, spec)
structure = simuverity_candidate_structure( ...
    model, string({spec.output_contract.name})');
semantic = structure.semantic_types;
storage = nnz(contains(semantic, ["battery", "cell"]));
switching = nnz(contains(semantic, ...
    ["switch", "contactor", "breaker", "fault"]));
audit = struct( ...
    "battery_or_cell_component_count", storage, ...
    "switching_or_fault_component_count", switching, ...
    "connected_public_output_count", structure.connected_output_count, ...
    "dynamic_state_block_count", structure.dynamic_block_count, ...
    "core_path_qualified", storage >= 1 && switching >= 1 && ...
        structure.connected_output_count == numel(spec.output_contract) && ...
        structure.dynamic_block_count >= 1);
end

function rows = localRows(names, widths)
rows = repmat(struct("name", "", "evidence_name", "", ...
    "width", 0, "interpolation", "linear"), numel(names), 1);
for k = 1:numel(names)
    rows(k).name = names(k);
    rows(k).evidence_name = names(k);
    rows(k).width = widths(k);
end
end

function [taskRoot, sharedRoot] = localRoots(taskId)
scriptRoot = fileparts(mfilename("fullpath"));
tasksRoot = fileparts(scriptRoot);
sharedRoot = fullfile(tasksRoot, "_shared");
repoRoot = tasksRoot;
for k = 1:3, repoRoot = fileparts(repoRoot); end
taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
end
